Actionscript.script:
手枪射击许可 = false;
手枪2射击许可 = false;
if (_parent.手枪属性.power)
{
	手枪射击许可 = true;
	射击速度 = _parent.手枪属性.interval;
	弹夹容量 = _parent.手枪属性.capacity;
	使用弹夹名称 = _parent.手枪属性.clipname;
	声音 = _parent.手枪属性.sound;
	霰弹值 = _parent.手枪属性.split;
	子弹散射度 = _parent.手枪属性.diffusion;
	发射效果 = _parent.手枪属性.muzzle;
	子弹种类 = _parent.手枪属性.bullet;
	子弹威力 = _parent.手枪属性.power + 20;
	if (_parent.短枪额外攻击加成倍率)
	{
		子弹威力 += _parent.手枪属性.power * _parent.短枪额外攻击加成倍率;
	}
	子弹速度 = _parent.手枪属性.velocity;
	击中地图效果 = _parent.手枪属性.bullethit;
	Z轴攻击范围 = _parent.手枪属性.bulletsize + 20;
	击倒率 = _parent.手枪属性.impact / 2;
	击中后子弹的效果 = _parent.手枪属性.targethit;

	//手枪射击间隔帧 = Math.floor(射击速度 * 30 / 1000);
	手枪射击间隔帧 =Math.floor((射击速度 + 20) * 0.7 * 30 / 1000);
	//弹夹容量的最大射击间隔帧 = Math.floor(21 / (弹夹容量 - _parent.手枪.value.shot + 弹夹容量));
	手枪射击间隔帧 = Math.max(手枪射击间隔帧, 1);
	单发弹数  = 1;
	// ── 射击节奏：2026-11-26 完全照搬 技能容器-死亡绽放 ──
	// 间隔帧由上方绽放公式逐枪算好（floor((interval+20)*0.7*30/1000)，下限 1），入口不再注入。
	// 间隔帧 ≤ 3 且弹种不含「横向」→ 纵向联弹：霰弹值 ×ceil(5/帧)、弹种加前缀、间隔帧固定 5。
	// 弹数记账（2026-11-27 三次裁定）：只有霰弹枪 1 扳机 = 1 发（联弹弹丸免费，原版口径）；
	// 其余枪类（冲锋枪/手枪/特殊/发射器等）联弹多少发就扣多少发。弹夹容量保持真实弹数，
	// 卸载不做任何折算 —— 任何跨释放的单位折算都会让 shot 翻倍污染，一律废弃。
	// 发数只由「间隔帧 + 动画窗口 + 弹夹」收束；后射/换弹打击由入口注入最低档封顶。
	if (手枪射击间隔帧 <= 3 && 子弹种类.indexOf("横向") == -1) {
		霰弹值 *= Math.ceil(5 / 手枪射击间隔帧);
		if (子弹种类.indexOf("纵向") == -1) 子弹种类 = "纵向联弹-" + 子弹种类;
		手枪射击间隔帧 = 5;
	}
	// 弹数记账（2026-11-27 三次裁定）：只有霰弹枪 1 扳机 = 1 发（联弹弹丸免费），
	// 其余枪类联弹多少发就扣多少发 —— 单发消耗 = 弹丸免费 ? 1 : 联弹后的霰弹值。
	if (_parent.__手枪搓招弹丸免费1) {
		单发消耗 = 1;
	} else {
		单发消耗 = 霰弹值;
	}
	// 修复旧版记账污染：卸载乘法会让 shot 超过真实弹夹容量，卡住后续所有释放
	if (_parent.手枪.value.shot > 弹夹容量) _parent.手枪.value.shot = 0;
	手枪发数上限 = _parent.__手枪搓招发数1;
	if (isNaN(手枪发数上限) || 手枪发数上限 < 1) 手枪发数上限 = 0;
}


if (_parent.手枪2属性.power)
{
	手枪2射击许可 = true;
	射击速度_2 = _parent.手枪2属性.interval;
	弹夹容量_2 = _parent.手枪2属性.capacity;
	使用弹夹名称_2 = _parent.手枪2属性.clipname;
	声音_2 = _parent.手枪2属性.sound;
	霰弹值_2 = _parent.手枪2属性.split;
	子弹散射度_2 = _parent.手枪2属性.diffusion;
	发射效果_2 = _parent.手枪2属性.muzzle;
	子弹种类_2 = _parent.手枪2属性.bullet;
	子弹威力_2 = _parent.手枪2属性.power + 20;
	if (_parent.短枪额外攻击加成倍率)
	{
		子弹威力_2 += _parent.手枪2属性.power * _parent.短枪额外攻击加成倍率;
	}
	子弹速度_2 = _parent.手枪2属性.velocity;
	击中地图效果_2 = _parent.手枪2属性.bullethit;
	Z轴攻击范围_2 = _parent.手枪2属性.bulletsize + 20;
	击倒率_2 = _parent.手枪2属性.impact / 2;
	击中后子弹的效果_2 = _parent.手枪2属性.targethit;


	//手枪射击间隔帧_2 = Math.ceil((射击速度_2 + 200) * 0.03 / 5);
	//手枪射击间隔帧_2 = Math.ceil((射击速度_2 + 200) * 0.2 * 30/ 1000);
	手枪射击间隔帧_2 =Math.floor((射击速度_2 + 10) * 0.8 * 30 / 1000);
	//弹夹容量的最大射击间隔帧_2 = Math.floor(21 / (弹夹容量_2 - _parent.手枪2.value.shot + 弹夹容量_2));
	手枪射击间隔帧_2 = Math.max(手枪射击间隔帧_2, 1);
	if (手枪射击间隔帧_2 <= 3 && 子弹种类_2.indexOf("横向") == -1) {
		霰弹值_2 *= Math.ceil(5 / 手枪射击间隔帧_2);
		if (子弹种类_2.indexOf("纵向") == -1) 子弹种类_2 = "纵向联弹-" + 子弹种类_2;
		手枪射击间隔帧_2 = 5;
	}
	// 手枪2 路同上：单发消耗 = 弹丸免费 ? 1 : 联弹后的霰弹值
	if (_parent.__手枪搓招弹丸免费2) {
		单发消耗_2 = 1;
	} else {
		单发消耗_2 = 霰弹值_2;
	}
	手枪发数上限_2 = _parent.__手枪搓招发数2;
	if (isNaN(手枪发数上限_2) || 手枪发数上限_2 < 1) 手枪发数上限_2 = 0;
}


子弹敌我属性 = _parent.是否为敌人 == true ? false : true;

// ── 自动换弹（2026-11-24 实装回填，与 手枪搓招容器-后射 同口径）──
// 换弹打击可自动换弹：弹匣打空即从背包扣一个弹夹重置 shot，换弹期间许可为 false。
function 手枪换弹()
{
	手枪射击许可 = false;
	if (_parent._name == _root.控制目标)
	{
		if (_root.singleSubmit(使用弹夹名称, 1, {source:"reload", reason:"death_bloom", mergeScope:"operation"}))
		{
			_parent.手枪.value.shot = 0;
			手枪射击许可 = true;
		}
	}
	else
	{
		_parent.手枪.value.shot = 0;
		手枪射击许可 = true;
	}
}
function 手枪2换弹()
{
	手枪2射击许可 = false;
	if (_parent._name == _root.控制目标)
	{
		if (_root.singleSubmit(使用弹夹名称_2, 1, {source:"reload", reason:"death_bloom", mergeScope:"operation"}))
		{
			_parent.手枪2.value.shot = 0;
			手枪2射击许可 = true;
		}
	}
	else
	{
		_parent.手枪2.value.shot = 0;
		手枪2射击许可 = true;
	}
}

if (手枪射击许可 && _parent.手枪.value.shot >= 弹夹容量)
{
	手枪射击许可 = false;
	手枪换弹();
}

if (手枪2射击许可 && _parent.手枪2.value.shot >= 弹夹容量_2)
{
	手枪2射击许可 = false;
	手枪2换弹();
}

onClipEvent (load) {
    // 初始化射击状态标志与换向计时器。
    // 攻击点实例（攻击点层帧 4 起）与本元件不同帧，load 时取不到；
    // 间隔帧与攻击点绑定统一延迟到 enterFrame 按需补读，避免 undefined 入参。
    手枪1已射击 = false;
    手枪2已射击 = false;
    // 发数上限计数：冲锋枪有上限时封顶；上限 0 = 不封顶，仍由间隔帧 + 窗口收束
    手枪1已发 = 0;
    手枪2已发 = 0;
    // 弹数主体仍由「间隔帧 + 射击窗口」收束；已发计数只用于冲锋枪的发数上限封顶。
    // 换向计时器（每5帧换向一次）
    换向计时器 = 0;
    换向间隔 = 5;
}
onClipEvent (unload) {
    // 2026-11-27：shot 按真实弹数记账（霰弹枪 1 扳机 1 发，其余枪类扣「单发消耗」），
    // 卸载不做任何折算 —— 旧乘法会在每次释放末尾放大 shot 并与下一次释放互相污染（已废弃）。
}

onClipEvent (enterFrame) {
    // 延迟初始化：许可/间隔帧由帧 2 脚本设置，攻击点实例自帧 4 起存在
    if (当前已持续帧1 == undefined) {
        当前已持续帧1 = _parent.手枪射击间隔帧;
        当前已持续帧2 = _parent.手枪射击间隔帧_2;
    }
    if (绑定攻击点1 == undefined) 绑定攻击点1 = _parent.攻击点1;
    if (绑定攻击点2 == undefined) 绑定攻击点2 = _parent.攻击点2;
    // 更新帧计数器
    当前已持续帧1++;
    当前已持续帧2++;
    换向计时器++;
    if (换向计时器 >= 换向间隔) {
        // 交换攻击点绑定
        if (手枪1已射击) {
            绑定攻击点1 =  绑定攻击点1 == _parent.攻击点1? _parent.攻击点2:_parent.攻击点1;
            手枪1已射击 = false;
        }
        if (手枪2已射击) {
            绑定攻击点2 =  绑定攻击点2 == _parent.攻击点1? _parent.攻击点2:_parent.攻击点1;
            手枪2已射击 = false;
        }

        换向计时器 = 0;
    }

    // 余弹不足一次扣弹（非霰弹枪按联弹发数扣）：开火前就得能把弹夹换掉，否则弹夹会停在
    // 「不够一次扣弹、也永远不触发换弹」的死角。手枪换弹 内有 singleSubmit + 许可互锁，无夹不刷屏。
    if (_parent.手枪射击许可 && _parent._parent.手枪.value.shot + _parent.单发消耗 > _parent.弹夹容量) {
        _parent.手枪换弹();
    }

    // ========== 手枪1射击逻辑 ==========
    if (_parent.手枪射击许可 && 
        当前已持续帧1 >= _parent.手枪射击间隔帧 && 
        绑定攻击点1 != undefined &&
        _parent._parent.手枪.value.shot + _parent.单发消耗 <= _parent.弹夹容量 &&
        (_parent.手枪发数上限 <= 0 || 手枪1已发 < _parent.手枪发数上限)) {

        _parent._parent.手枪.value.shot += _parent.单发消耗;

        // 检查换弹（换弹打击可自动换弹；剩余不够一次扣弹也换）
        if (_parent._parent.手枪.value.shot + _parent.单发消耗 > _parent.弹夹容量) {
            _parent.手枪换弹();
        }

        // 更新UI子弹数
        if (_parent._parent.攻击模式 == "双枪" || 
            _parent._parent.攻击模式 == "手枪" || 
            _parent._parent.攻击模式 == "手枪2") {
            _root.玩家信息界面.玩家必要信息界面.子弹数 = 
                _parent.弹夹容量 - _parent._parent.手枪.value.shot;
		}

        当前已持续帧1 = 0;
        var 子弹属性 = _root.子弹属性初始化(绑定攻击点1);

        // 设置子弹属性（使用手枪1的属性）
        子弹属性.声音 = _parent.声音;
        子弹属性.霰弹值 = _parent.霰弹值;
        子弹属性.子弹散射度 = _parent.子弹散射度 + 3;
        子弹属性.子弹种类 = _parent.子弹种类;
        子弹属性.发射效果 = _parent.发射效果;
        子弹属性.击中地图效果 = _parent.击中地图效果;


        // 伤害类型设置
        if (_parent._parent.手枪伤害类型) {
            子弹属性.伤害类型 = _parent._parent.手枪伤害类型;
        }
        if (_parent._parent.手枪魔法伤害属性) {
            子弹属性.魔法伤害属性 = _parent._parent.手枪魔法伤害属性;
        }
        if (_parent._parent.手枪毒) {
            子弹属性.毒 = _parent._parent.手枪毒;
        }
        if (_parent._parent.手枪吸血) {
            子弹属性.吸血 = _parent._parent.手枪吸血;
        }
        if (_parent._parent.手枪击溃) {
            子弹属性.血量上限击溃 = _parent._parent.手枪击溃;
        }

        // 暴击逻辑
        if (_parent._parent.手枪暴击) {
            if (!isNaN(Number(_parent._parent.手枪暴击))) {
				子弹属性.暴击率 = Number(_parent._parent.手枪暴击);
                子弹属性.暴击 = function(当前子弹) {
                    if (_root.成功率(当前子弹.暴击率)) {
                        return 1.5;
                    }
                    return 1;
                };
            } else if (_parent._parent.手枪暴击 == "满血暴击") {
                子弹属性.暴击 = function(当前子弹) {
                    if (当前子弹.hitTarget.hp >= 当前子弹.hitTarget.hp满血值) {
                        return 1.5;
                    }
                    return 1;
                };
            }
        }

        // 斩杀逻辑
        if (_parent._parent.手枪斩杀 && !isNaN(Number(_parent._parent.手枪斩杀))) {
            子弹属性.斩杀 = Number(_parent._parent.手枪斩杀);
        }

        // 子弹威力计算
        var 自机 = _root.获得父节点(this, 2);
        子弹属性.子弹威力 = _parent.子弹威力 * (1.2 + _parent._parent.技能等级 * 0.1);

        // 子弹速度计算（根据绑定攻击点调整方向）
        子弹属性.子弹速度 = _parent.子弹速度 + 5 + _parent._parent.技能等级 * 0.5;
        子弹属性.子弹速度 = Math.abs(子弹属性.子弹速度); // 固定向前射击（枪口在身前）

        // 其他属性
        子弹属性.Z轴攻击范围 = _parent.Z轴攻击范围;
        子弹属性.击倒率 = _parent.击倒率;
        子弹属性.击中后子弹的效果 = _parent.击中后子弹的效果;


        // 发射子弹
        _root.子弹区域shoot传递(子弹属性);

        // 更新射击状态
        手枪1已射击 = true;
        手枪1已发++;

    }

    if (_parent.手枪2射击许可 && _parent._parent.手枪2.value.shot + _parent.单发消耗_2 > _parent.弹夹容量_2) {
        _parent.手枪2换弹();
    }

    // ========== 手枪2射击逻辑 ==========
    if (_parent.手枪2射击许可 && 
        当前已持续帧2 >= _parent.手枪射击间隔帧_2 && 
        绑定攻击点2 != undefined &&
        _parent._parent.手枪2.value.shot + _parent.单发消耗_2 <= _parent.弹夹容量_2 &&
        (_parent.手枪发数上限_2 <= 0 || 手枪2已发 < _parent.手枪发数上限_2)) {

        _parent._parent.手枪2.value.shot += _parent.单发消耗_2;

        // 检查换弹（手枪2 路，同上）
        if (_parent._parent.手枪2.value.shot + _parent.单发消耗_2 > _parent.弹夹容量_2) {
            _parent.手枪2换弹();
        }

        // 更新UI子弹数
        if (_parent._parent.攻击模式 == "双枪" || 
            _parent._parent.攻击模式 == "手枪" || 
            _parent._parent.攻击模式 == "手枪2") {
            _root.玩家信息界面.玩家必要信息界面.子弹数_2 = 
                _parent.弹夹容量_2 - _parent._parent.手枪2.value.shot;
		}

        当前已持续帧2 = 0;
        var 子弹属性 = _root.子弹属性初始化(绑定攻击点2);

        // 设置子弹属性（使用手枪2的属性）
        子弹属性.声音 = _parent.声音_2;
        子弹属性.霰弹值 = _parent.霰弹值_2;
        子弹属性.子弹散射度 = _parent.子弹散射度_2 + 3;
        子弹属性.子弹种类 = _parent.子弹种类_2;
        子弹属性.发射效果 = _parent.发射效果_2;
        子弹属性.击中地图效果 = _parent.击中地图效果_2;


        // 伤害类型设置
        if (_parent._parent.手枪2伤害类型) {
            子弹属性.伤害类型 = _parent._parent.手枪2伤害类型;
        }
        if (_parent._parent.手枪2魔法伤害属性) {
            子弹属性.魔法伤害属性 = _parent._parent.手枪2魔法伤害属性;
        }
        if (_parent._parent.手枪2毒) {
            子弹属性.毒 = _parent._parent.手枪2毒;
        }
        if (_parent._parent.手枪2吸血) {
            子弹属性.吸血 = _parent._parent.手枪2吸血;
        }
        if (_parent._parent.手枪2击溃) {
            子弹属性.血量上限击溃 = _parent._parent.手枪2击溃;
        }

        // 暴击逻辑
        if (_parent._parent.手枪2暴击) {
            if (!isNaN(Number(_parent._parent.手枪2暴击))) {
				子弹属性.暴击率 = Number(_parent._parent.手枪2暴击);
                子弹属性.暴击 = function(当前子弹) {
                    if (_root.成功率(当前子弹.暴击率)) {
                        return 1.5;
                    }
                    return 1;
                };
            } else if (_parent._parent.手枪2暴击 == "满血暴击") {
                子弹属性.暴击 = function(当前子弹) {
                    if (当前子弹.hitTarget.hp >= 当前子弹.hitTarget.hp满血值) {
                        return 1.5;
                    }
                    return 1;
                };
            }
        }

        // 斩杀逻辑
        if (_parent._parent.手枪2斩杀 && !isNaN(Number(_parent._parent.手枪2斩杀))) {
            子弹属性.斩杀 = Number(_parent._parent.手枪2斩杀);
        }

        // 子弹威力计算
        var 自机 = _root.获得父节点(this, 2);
        子弹属性.子弹威力 = _parent.子弹威力_2 * (1.2 + _parent._parent.技能等级 * 0.1);

        // 子弹速度计算（根据绑定攻击点调整方向）
        子弹属性.子弹速度 = _parent.子弹速度_2 + 5 + _parent._parent.技能等级 * 0.5;
        子弹属性.子弹速度 = Math.abs(子弹属性.子弹速度); // 固定向前射击（枪口在身前）

        // 其他属性
        子弹属性.Z轴攻击范围 = _parent.Z轴攻击范围_2;
        子弹属性.击倒率 = _parent.击倒率_2;
        子弹属性.击中后子弹的效果 = _parent.击中后子弹的效果_2;


        // 发射子弹
        _root.子弹区域shoot传递(子弹属性);

        // 更新射击状态
        手枪2已射击 = true;
        手枪2已发++;
    }

}

onClipEvent(load){
	子弹属性 = _root.子弹属性初始化(this);
	var 自机 = _parent._parent;
	//以下部分只需要更改需要更改的属性,其余部分可注释掉
	子弹属性.声音 = "";
	子弹属性.霰弹值 = 1;
	子弹属性.子弹散射度 = 0;
	子弹属性.子弹种类 = "近战联弹";
	子弹属性.子弹威力 =  自机.空手攻击力 * 1+ 自机.内力 * 1;

	if (_parent._parent.被动技能.拳脚攻击 && _parent._parent.被动技能.拳脚攻击.启用)
	{
		子弹属性.子弹威力 += _parent._parent.空手攻击力 * _parent._parent.被动技能.拳脚攻击.等级 * 0.1;
	}
	/*if (_parent._parent.mp攻击加成)
	{
		子弹属性.子弹威力 += _parent._parent.mp攻击加成;
	}*/
	/*if (_parent._parent.被动技能.拳脚攻击 && _parent._parent.被动技能.拳脚攻击.等级)
	{
		子弹属性.子弹威力 += _parent._parent.空手攻击力 * _parent._parent.被动技能.拳脚攻击.等级 / 10;
	}*/
	子弹属性.子弹速度 = 0;
	子弹属性.Z轴攻击范围 = 30;
	子弹属性.击倒率 = 1;
	子弹属性.不硬直 = true;
	子弹属性.水平击退速度 = 20;
	子弹属性.垂直击退速度 = 2;
	子弹属性.击中后子弹的效果 = "";
	//非常用
	/*
	子弹属性.垂直击退速度 = NaN;
	子弹属性.发射效果 = "";
	子弹属性.击中地图效果 = "火花".
	子弹属性.命中率 = NaN.
	子弹属性.固伤 = NaN;
	子弹属性.百分比伤害 = NaN;
	子弹属性.血量上限击溃 = NaN;
	子弹属性.防御粉碎 = NaN;
	*/
	子弹属性.区域定位area = this.area;
	/*
	//已初始化内容，通常不需要重复赋值，可注释掉
	子弹属性.发射者 = 子弹属性.发射者.
	子弹属性.shootX = 子弹属性.shootX;
	子弹属性.shootY = 子弹属性.shootY;
	子弹属性.shootZ = 子弹属性.shootZ;
	子弹属性.子弹敌我属性 = 子弹属性.子弹敌我属性;
	*/
	_root.子弹区域shoot传递(子弹属性);
}

onClipEvent (load) {
	_parent._parent.skillShadow = this;
	if (!_root.是否阴影)
	{
		this._visible = false;
	}
	缩放乘数 = 3.611 * 175 / _parent._parent.身高;
	if (_parent.技能浮空 == true)
	{
		if (_parent._parent.浮空)
		{
			this._y = 233.05 + (_parent._parent.起始Y - _parent._parent._y - _parent._parent.垂直速度) * 缩放乘数;
		}
	}
}
onClipEvent (enterFrame) {
	if (_root.是否阴影 and _parent._parent.浮空)
	{
		this._y = 233.05 + (_parent._parent.起始Y - _parent._parent._y - _parent._parent.垂直速度) * 缩放乘数;
	}
	else
	{
		this._y = 233.05;
	}
}
